<?php require_once __DIR__.'/includes/functions.php';$admin=require_admin();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed.');}check_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$id||$id===(int)$admin['id']){http_response_code(400);exit('Invalid user ID or self-deletion not allowed.');}$stmt=db()->prepare('SELECT avatar FROM users WHERE id=?');$stmt->execute([$id]);$avatar=$stmt->fetchColumn();$stmt=db()->prepare('DELETE FROM users WHERE id=?');$stmt->execute([$id]);if($avatar && preg_match('/^[a-f0-9]{40}\.(jpg|png|webp)$/',$avatar))@unlink(__DIR__.'/uploads/'.$avatar);flash('success','User deleted.');redirect('users.php');
